        // Case 3: c+z <= a+x + b+y
        ans += countInvalid(c, a, b, l);
        System.out.println(total - ans);
    }

    // Count invalid cases where the first stick is too short
    static long countInvalid(int a, int b, int c, int l) {
        long res = 0;
        // For each possible increment of the first stick (x)
        for (int x = 0; x <= l; x++) {
            int na = a + x;
            // Find minimum required increments for b and c to satisfy na <= b+y + c+z
            // na <= (b + y) + (c + z) => y + z >= na - b - c
            int minYZ = Math.max(0, na - b - c);
            // Total remaining increments for y and z
            int rem = l - x;
            if (minYZ > rem) continue;
            // Number of (y,z) pairs with y+z >= minYZ and y+z <= rem
            // Total pairs: (rem + 1) * (rem + 2) / 2
            // Subtract pairs where y+z < minYZ
            int invalid = minYZ > 0 ? (minYZ - 1) * minYZ / 2 : 0;
            res += (rem + 1) * (rem + 2) / 2 - invalid;
