        long bad = 0;

        // Compute bad cases for each pair
        bad += countBad(a, b, c, l);
        bad += countBad(a, c, b, l);
        bad += countBad(b, c, a, l);

        // Subtract overcounted cases where all three are bad
        // These are cases where x + y + z = l and x >= a + b, y >= a + c, z >= b + c
        // But since a + b + a + c + b + c = 2*(a + b + c) > l (since l <= 3e5 and a,b,c >=1)
        // So no overcounting
        System.out.println(total - bad);
    }

    static long countBad(long a, long b, long c, long l) {
        // Count cases where a + x <= b + y + c + z, i.e., x - y - z <= b + c - a
        // But we need to count all (x,y,z) with x + y + z <= l and x <= y + z + (b + c - a)
        // This is equivalent to counting all (x,y,z) with x + y + z <= l and x <= y + z + (b + c - a)
        // Let's compute the complement: x > y + z + (b + c - a)
        // Which is x - y - z > b + c - a
        // So bad cases are those where x > y + z + (b + c - a)
        // Let d = b + c - a
        // We need to count (x,y,z) with x + y + z <= l and x > y + z + d
        // Let s = y + z, then x > s + d and x + s <= l
        // So s + d < x <= l - s
        // Which implies s + d < l - s => 2s < l - d => s < (l - d)/2
        // For each s from 0 to min(l, (l - d - 1)/2), count valid x and (y,z) pairs
        long d = b + c - a;
        long bad = 0;

        // s ranges from 0 to l
        // For each s, x must be > s + d and x <= l - s
        // So x ranges from max(0, s + d + 1) to l - s
        // Number of x values: max(0, (l - s) - (s + d + 1) + 1) = max(0, l - 2s - d)
        // Number of (y,z) pairs with y + z = s: s + 1
        // But s can be at most l (since y + z <= l - x and x >= 0)
        // Also, s + d + 1 <= l - s => 2s <= l - d - 1 => s <= (l - d - 1)/2

        long maxS = (l - d - 1) / 2;
        if (maxS < 0) return 0;

        for (long s = 0; s <= maxS && s <= l; s++) {
            long xCount = l - 2 * s - d;
            if (xCount <= 0) continue;
            long yzCount = s + 1;
            bad += xCount * yzCount;
        }

        return bad;
    }
